    case 1:
      if (lookahead == 'I') ADVANCE(21);
      if (lookahead == 'i') ADVANCE(22);
      if (lookahead == 'E' ||
          lookahead == 'e') ADVANCE(23);
      if (lookahead == 'K' ||
          lookahead == 'k') ADVANCE(24);
